const trainingDays=[['7','السبت'],['1','الأحد'],['2','الاثنين'],['3','الثلاثاء'],['4','الأربعاء'],['5','الخميس'],['6','الجمعة']];
function sessionForDate(date){return String(new Date(date+'T12:00:00').getDay()+1)}
function trainingDate(session,date=selected){return shift(date,-((new Date(date+'T12:00:00').getDay()+1)%7)+trainingDays.findIndex(d=>d[0]===session))}
function trainingDayName(session){return trainingDays.find(d=>d[0]===session)?.[1]||session}
function weeklyExercises(){const days=[
[['Chest Press','صدر','8–12','Dumbbell Bench Press'],['Incline Dumbbell Press','صدر','8–12','Incline Chest Press Machine'],['Cable Fly','صدر','12–15','Pec Deck']],
[['Lat Pulldown','ظهر','8–12','Assisted Pull-up'],['Seated Cable Row','ظهر','8–12','Chest-supported Dumbbell Row'],['One-arm Dumbbell Row','ظهر','10–12 / جهة','One-arm Cable Row']],
[['Leg Press','رجل','8–12','Goblet Squat'],['Dumbbell Romanian Deadlift','رجل','8–12','Hip Hinge'],['Leg Curl','رجل','10–15','Sliding Leg Curl'],['Calf Raise','رجل','12–15','Seated Calf Raise']],
[['Shoulder Press','كتف','8–12','Dumbbell Shoulder Press'],['Lateral Raise','كتف','12–15','Cable Lateral Raise'],['Reverse Pec Deck','كتف','12–15','Rear-delt Dumbbell Fly']],
[['Dumbbell Curl','باي','10–12','Cable Curl'],['Hammer Curl','باي','10–12','Rope Curl'],['Triceps Pushdown','تراي','10–12','Resistance Band Pushdown'],['Overhead Cable Extension','تراي','10–12','Dumbbell Triceps Extension'],['Dead Bug','بطن','8–12 / جهة','Bird Dog']]];
return days.flatMap((rows,d)=>rows.map(([exercise,group,reps,alternative],i)=>({id:'weekly-v1-'+d+'-'+i,session:String(d+1),exercise,group,reps,alternative,sets:3,weight:'',notes:'اختر وزنًا مناسبًا لحركة سليمة ودون ألم. الجولة الرابعة اختيارية في سجل الأداء.'})));}
function installWeeklyPlan(){if(!window.fitnessAccount?.owner||activeProfile!=='default'||data.training.weeklySplitVersion)return;const next=structuredClone(data);next.training.previousExercises=next.training.exercises||[];next.training.exercises=weeklyExercises();next.training.weeklySplitVersion=1;next.training.weeklySplitActive=true;next.targets.workoutDays=5;validate(next);commit(next,'تم تجهيز أسبوعك: الأحد صدر، الجمعة راحة والسبت كارديو اختياري')}
function weeklyDayDetail(session){if(data.training.weeklySplitActive){if(session==='6')return 'راحة';if(session==='7')return 'كارديو اختياري'}const groups=[...new Set((data.training.exercises||[]).filter(x=>x.session===session).map(x=>x.group))];return groups.join(' + ')||'بدون تمارين مخططة'}
let trainingSession='1',planEditing=null;
const planDialog=document.createElement('dialog');planDialog.setAttribute('aria-label','تعديل خطة التمرين');document.body.append(planDialog);
function planButton(text,act,extra=''){return `<button class="button secondary" data-program="${act}" ${extra}>${text}</button>`}
function renderTrainingPlan(){trainingSession=sessionForDate(selected);const plan=data.training.exercises||[],rows=plan.filter(x=>x.session===trainingSession),done=rows.filter(x=>data.training[selected+':'+x.id]===true).length;return `<div class="card"><div class="card-head"><div><h2>برنامج التمارين</h2><p class="sub">خطة مستقلة لكل ملف. الإنجاز يخص ${pretty(selected)}.</p></div>${planButton('+ تمرين مخطط','add')}</div><div class="training-week">${trainingDays.map(([n,label])=>`<button class="button ${trainingSession===n?'':'secondary'}" data-program="session" data-id="${n}" ${trainingSession===n?'aria-current="date"':''}><strong>${label}</strong><small>${pretty(trainingDate(n),{day:'numeric',month:'short'})}</small><span>${esc(weeklyDayDetail(n))}</span></button>`).join('')}</div><div class="quick-buttons">${planButton('الأسبوع السابق','previous-week')}${planButton('الأسبوع التالي','next-week')}${planButton('استخدام قالب PDF المرفق','template')}</div><h3>${trainingDayName(trainingSession)} · ${esc(weeklyDayDetail(trainingSession))}</h3><p class="notice">الإنجاز والأداء محفوظان بتاريخ ${pretty(selected)}. عدّل التمارين والبدائل حسب حاجتك. تأشير الهدف لا يسجّل أوزانًا أو عدات فعلية.</p>${data.training.weeklySplitActive&&trainingSession==='6'?'<p class="notice">يوم راحة من التمارين المخططة.</p>':''}${data.training.weeklySplitActive&&trainingSession==='7'?`<p class="notice">كلاس كارديو اختياري بحسب رغبتك وتعافيك؛ لا يُحسب ضمن أيام المقاومة الخمسة.</p>${planButton('تسجيل كلاس كارديو','cardio')}`:''}<p><strong>${done} / ${rows.length}</strong> تمرين تم إنجازه في الجلسة المحددة</p>${progress(done,rows.length)}${rows.map(x=>`<article class="record"><div class="record-head"><div><h3>${esc(x.exercise)}</h3><p class="sub">${x.sets} جولات × ${esc(x.reps)} عدات${x.weight!==''?' · '+fmt(x.weight)+' كجم مستهدف':''}</p>${x.alternative&&x.alternative!=='—'?`<p class="sub">البديل: ${esc(x.alternative)}</p>`:''}${x.notes?`<p class="sub">${esc(x.notes)}</p>`:''}</div><label class="check-label"><input type="checkbox" data-program-done="${esc(x.id)}" ${data.training[selected+':'+x.id]?'checked':''}> تم الهدف</label></div><div class="quick-buttons">${planButton('تسجيل الأداء الفعلي','log',`data-id="${esc(x.id)}"`)}${planButton('تعديل','edit',`data-id="${esc(x.id)}"`)}${planButton('حذف','delete',`data-id="${esc(x.id)}"`)}</div></article>`).join('')||'<p class="empty">لا توجد تمارين مقاومة مخططة لهذا اليوم.</p>'}</div>`}
const originalWorkoutsView=renderWorkouts;renderWorkouts=()=>renderTrainingPlan()+originalWorkoutsView();
function editPlannedExercise(row){planEditing=row?.id||null;const x=row||{session:trainingSession,sets:3};planDialog.innerHTML=`<form id="planForm"><div class="dialog-head"><h2>${row?'تعديل التمرين المخطط':'إضافة تمرين للخطة'}</h2><button class="icon-button" type="button" data-program="close">×</button></div><div class="form-grid"><label>اليوم<select name="session">${trainingDays.map(([id,name])=>`<option value="${id}" ${x.session===id?'selected':''}>${name}</option>`).join('')}</select></label>${input('exercise','التمرين',x.exercise||'','text',true,'maxlength="120"')}${select('group','المجموعة',['صدر','ظهر','كتف','رجل','باي','تراي','بطن','كامل الجسم'],x.group||'كامل الجسم')}${number('sets','الجولات',x.sets,true,1,1,4)}${input('reps','العدات المستهدفة',x.reps||'8–12','text',true,'maxlength="40"')}${number('weight','الوزن المستهدف كجم (اختياري)',x.weight||'',false,0,.5,600)}${input('alternative','البدائل',x.alternative||'','text',false,'maxlength="300"')}${textarea('notes','ملاحظات',x.notes)}</div><p class="danger" id="planError"></p><div class="dialog-actions"><button class="button">حفظ الخطة</button></div></form>`;planDialog.showModal();$('#planForm').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),next=structuredClone(data),entry={...f,id:planEditing||uid(),sets:Number(f.sets),weight:f.weight===''?'':Number(f.weight)};next.training.exercises=[...(next.training.exercises||[]).filter(x=>x.id!==entry.id),entry];try{validate(next);if(commit(next,'تم حفظ الخطة'))planDialog.close()}catch(err){$('#planError').textContent=err.message}}}
document.addEventListener('change',e=>{const id=e.target.dataset.programDone;if(id){const next=structuredClone(data);next.training[selected+':'+id]=e.target.checked;commit(next,'تم تحديث الإنجاز')}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-program]');if(!b)return;const a=b.dataset.program,id=b.dataset.id,row=(data.training.exercises||[]).find(x=>x.id===id);if(a==='session')setDate(trainingDate(id));if(a==='previous-week')setDate(shift(selected,-7));if(a==='next-week')setDate(shift(selected,7));if(a==='cardio')openForm('workout',{exercise:'كلاس كارديو',exerciseType:'كارديو',group:'كامل الجسم',sets:[]},true);if(a==='close')planDialog.close();if(a==='add')editPlannedExercise();if(a==='edit'&&row)editPlannedExercise(row);if(a==='template'){if(data.training.exercises?.length&&!confirm('استبدال الخطة الحالية بقالب الملف؟ سجلات التدريب الفعلية لن تتغير.'))return;const next=structuredClone(data);next.training.weeklySplitActive=false;next.training.exercises=referenceProgram.map(x=>({...x,id:uid()}));commit(next,'تم تحميل القالب المرجعي')}if(a==='delete'&&row&&confirm('حذف هذا التمرين من الخطة؟')){const next=structuredClone(data);next.training.exercises=next.training.exercises.filter(x=>x.id!==id);commit(next)}if(a==='log'&&row){openForm('workout',{exercise:row.exercise,group:row.group,sets:[],notes:'الخطة: '+row.sets+' جولات × '+row.reps,exerciseType:'مقاومة'},true);for(let i=1;i<=row.sets;i++){const el=$('#fields input[name=w'+i+']');if(el&&row.weight!=='')el.value=row.weight}}});
const previousNutritionView=window.renderNutritionPlan;window.renderNutritionPlan=()=>{const latest=[...data.measurements].filter(x=>!x.reviewRequired).sort((a,b)=>(b.measuredAt||b.date).localeCompare(a.measuredAt||a.date))[0];return (latest?`<div class="card"><h2>خطة من أحدث قياس</h2><p class="sub">${pretty(latest.date)} · ${fmt(latest.weight)} كجم${latest.bmr?' · BMR '+fmt(latest.bmr):''}</p><p>راجع النشاط والهدف والحساسيات، ثم أنشئ خطة الأسبوع تلقائيًا.</p>${fb('مراجعة القياسات وإنشاء الخطة','intake')}</div>`:'')+previousNutritionView()};
const originalSettingsView=renderSettings;renderSettings=()=>`<div class="card"><h2>حسابك وصلاحياتك</h2><p>${esc(window.fitnessAccount?.email||'حساب موثّق')}</p><p class="notice">كل مستخدم يدخل بحسابه ويعدّل بياناته فقط. الملفات التابعة التي تنشئها داخل حسابك تديرها أنت؛ لا تمنح صاحب الاسم دخولًا مستقلًا.</p><p class="sub">لدعوة شخص ببريده، أضفه من مشاركة التطبيق بصفة Viewer. هذه الصفة تسمح باستخدام التطبيق وتعديل سجله الخاص، ولا تسمح بتعديل تصميم البرنامج أو سجلات الآخرين.</p><div class="quick-buttons"><a class="button secondary" href="/signin-with-chatgpt?return_to=%2F" target="_top">تجديد تسجيل الدخول</a></div></div>`+originalSettingsView();
async function importOwnerHistory(){if(!window.fitnessAccount?.owner||activeProfile!=='default')return;try{await syncNow();const r=await fetch('/api/source-history',{credentials:'same-origin',cache:'no-store',headers:{'x-fitness-account':accountScope}});if(!r.ok)return;const {measurements,historyVersion}=await r.json();if(data.nutrition.sourceHistoryVersion===historyVersion)return;const next=structuredClone(data);let count=0;for(const m of measurements){const old=next.measurements.find(x=>x.id===m.id);if(!old){next.measurements.push(m);count++}else{for(const key of Object.keys(m))if(old[key]===undefined)old[key]=m[key]}}next.nutrition.sourceHistoryImported=true;next.nutrition.sourceHistoryVersion=historyVersion;validate(next);commit(next,count?'تم استيراد '+count+' قياسًا بتاريخها الأصلي':'تم ربط سجل القياسات')}catch(e){notify('تعذر استيراد سجل القياسات: '+e.message,true)}}
const originalProgressView=renderProgress;renderProgress=()=>{const review=data.measurements.filter(x=>x.reviewRequired);return (review.length?`<div class="card"><h2>قياسات تحتاج مراجعتك</h2><p class="sub">حُفظت كما وردت في الملف، واستُبعدت من اتجاه الوزن والخطة حتى تأكيدك.</p>${review.map(x=>`<div class="goal-row"><span>${esc(x.measuredAt||x.date)} · ${fmt(x.weight)} كجم</span><button class="button secondary" data-approve-measure="${esc(x.id)}">هذا قياسي، اعتمده</button></div>`).join('')}</div>`:'')+originalProgressView()};
document.addEventListener('click',e=>{const id=e.target.closest('[data-approve-measure]')?.dataset.approveMeasure;if(!id)return;const next=structuredClone(data),m=next.measurements.find(x=>x.id===id);if(m){m.reviewRequired=false;commit(next)}});
const originalIntakeOpen=openFeature;openFeature=function(kind){originalIntakeOpen(kind);if(kind==='intake'){const latest=[...data.measurements].filter(x=>!x.reviewRequired).sort((a,b)=>(b.measuredAt||b.date).localeCompare(a.measuredAt||a.date))[0];if(!data.nutrition.intake&&window.fitnessAccount?.owner&&activeProfile==='default'){const form=$('#featureForm');form.elements.age.value=new Date().getFullYear()-1984;form.elements.height.value=175;}if(latest&&!data.nutrition.intake){for(const k of ['date','weight','bfr','bmr']){const el=$('#featureForm').elements[k];if(el&&latest[k]!=null)el.value=latest[k]}}}};
render();importOwnerHistory();
const intakeWithHistory=openFeature;openFeature=function(kind){intakeWithHistory(kind);if(kind==='intake'){const form=$('#featureForm'),openedProfile=activeProfile;const current=()=>featureDialog.open&&featureKind==='intake'&&activeProfile===openedProfile&&form.contains(btn);const btn=document.createElement('button');btn.type='button';btn.className='button';btn.textContent='قراءة أرقام InBody من الصورة';$('#reportPreview').after(btn);btn.onclick=async()=>{const file=$('#reportImage').files[0];if(!file){$('#featureError').textContent='اختر صورة التقرير أولًا.';return}if(file.size>15000000){$('#featureError').textContent='اختر صورة أقل من 15 ميجابايت.';return}btn.disabled=true;$('#featureError').textContent='جارٍ قراءة التقرير…';let url;try{url=URL.createObjectURL(file);const img=new Image();img.src=url;await img.decode();const scale=Math.min(1,2000/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const r=await fetch('/api/inbody-photo',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json','x-fitness-account':accountScope},body:JSON.stringify({image:canvas.toDataURL('image/jpeg',.9)})});const b=await r.json();if(!current())return;if(!r.ok)throw Error(b.error==='insufficient_quota'?'حساب API المرتبط رفض الطلب بسبب الرصيد أو الفوترة. راجع حساب المفتاح؛ حد الميزانية المتبقي وحده لا يؤكد توفر الرصيد.':b.error==='rate_limited'?'حد طلبات مؤقت. انتظر دقيقة وأعد المحاولة.':b.error==='no_report'?'الصورة لا تحتوي تقريرًا واضحًا. صوّر التقرير نفسه.':b.error==='sign_in_required'?'جدد تسجيل الدخول ثم أعد المحاولة.':'تعذرت قراءة التقرير. يمكنك إدخال القيم يدويًا.');for(const k of ['age','height','weight','bfr','muscleWeight','totalMuscleMass','fatMass','leanWeight','waterLiters','visceralFat','bmr','device'])$('#featureForm').elements[k].value=b.report[k]??'';if(b.report.sex)$('#featureForm').elements.sex.value=b.report.sex;$('#featureForm').elements.date.value=b.report.measuredDate||'';$('#featureError').textContent='راجع القيم وتاريخ التقرير قبل الحفظ. '+(b.report.warning||'');}catch(e){if(current())$('#featureError').textContent=e.message}finally{btn.disabled=false;if(url)URL.revokeObjectURL(url)}}}};
